# Chance calculation helper (legacy -- kept for backward compatibility, not used by the
# v4 UNIVERSITIES entries below, which carry their own "scores" from the source list)
def calc_chance(gpa_min_pct, toefl_needed, aps_needed, police_needed, medical_needed,
                qs_rank_num, notes=""):
    """Returns a chance string based on Vinay's profile vs requirements."""
    base = 80
    if gpa_min_pct:
        gap = PROFILE["cgpa_expected"] * 10 - gpa_min_pct
        if gap < -5:   base -= 30
        elif gap < 0:  base -= 15
        elif gap < 5:  base -= 5
    if qs_rank_num and qs_rank_num < 50:   base -= 20
    elif qs_rank_num and qs_rank_num < 100: base -= 10
    elif qs_rank_num and qs_rank_num < 200: base -= 5
    if police_needed or medical_needed: base -= 40  # blocked
    if base >= 80: return "High"
    if base >= 60: return "Medium-High"
    if base >= 45: return "Medium"
    if base >= 30: return "Reach"
    return "Blocked"


